// Expo config plugin for the Rust transport. Not generated by ubrn.
//
// The static library carries Rust `#[link(kind = "framework")]` directives that a
// staticlib cannot pass on to Xcode's linker, so system frameworks the Rust
// dependencies need are linked into the app target here.
const { withXcodeProject } = require('expo/config-plugins');

// iroh → netwatch/netdev and n0-dns-resolver read DNS and proxy settings via SCDynamicStore.
const IOS_FRAMEWORKS = ['SystemConfiguration.framework'];

module.exports = function withSovraRemote(config) {
  return withXcodeProject(config, (cfg) => {
    for (const framework of IOS_FRAMEWORKS) {
      cfg.modResults.addFramework(framework, { weak: false });
    }
    return cfg;
  });
};
